CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(200) NOT NULL UNIQUE, password_hash VARCHAR(500) NOT NULL, role VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, must_change_password BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL);
CREATE TABLE projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', color VARCHAR(20) NOT NULL DEFAULT '#6b5ce7', storage_quota_mb BIGINT NOT NULL DEFAULT 100, runtime_quota_seconds BIGINT NOT NULL DEFAULT 36000, compute_resource_id BIGINT, storage_resource_id BIGINT, created_at VARCHAR(40) NOT NULL);
CREATE TABLE memberships (project_id BIGINT NOT NULL REFERENCES projects(id), user_id BIGINT NOT NULL REFERENCES users(id), PRIMARY KEY(project_id,user_id));
CREATE TABLE resources (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, type VARCHAR(20) NOT NULL, capacity BIGINT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at VARCHAR(40) NOT NULL);
ALTER TABLE projects ADD CONSTRAINT fk_compute FOREIGN KEY(compute_resource_id) REFERENCES resources(id);
ALTER TABLE projects ADD CONSTRAINT fk_storage FOREIGN KEY(storage_resource_id) REFERENCES resources(id);
CREATE TABLE datasets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id), owner_id BIGINT NOT NULL REFERENCES users(id), name VARCHAR(120) NOT NULL, description TEXT NOT NULL, source TEXT NOT NULL, license VARCHAR(200) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE dataset_versions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, dataset_id BIGINT NOT NULL REFERENCES datasets(id), version_number INT NOT NULL, object_key VARCHAR(100) NOT NULL UNIQUE, checksum VARCHAR(64) NOT NULL, bytes BIGINT NOT NULL, row_count INT NOT NULL, column_count INT NOT NULL, schema_json TEXT NOT NULL, archived BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL, UNIQUE(dataset_id,version_number));
CREATE TABLE experiments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id), name VARCHAR(120) NOT NULL, notes TEXT NOT NULL, tags VARCHAR(500) NOT NULL DEFAULT '', created_at VARCHAR(40) NOT NULL);
CREATE TABLE jobs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id), user_id BIGINT NOT NULL REFERENCES users(id), experiment_id BIGINT NOT NULL REFERENCES experiments(id), dataset_version_id BIGINT NOT NULL REFERENCES dataset_versions(id), name VARCHAR(120) NOT NULL, model VARCHAR(40) NOT NULL, target_column VARCHAR(100) NOT NULL, parameters_json TEXT NOT NULL, seed INT NOT NULL, test_fraction DOUBLE PRECISION NOT NULL, submission_key VARCHAR(100) NOT NULL, parent_job_id BIGINT REFERENCES jobs(id), state VARCHAR(20) NOT NULL DEFAULT 'queued', stage VARCHAR(20) NOT NULL DEFAULT 'queued', cancel_requested BOOLEAN NOT NULL DEFAULT FALSE, lease_until BIGINT NOT NULL DEFAULT 0, metrics_json TEXT, artifact_key VARCHAR(100), artifact_checksum VARCHAR(64), artifact_bytes BIGINT NOT NULL DEFAULT 0, error TEXT, runtime_ms BIGINT NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL, started_at VARCHAR(40), finished_at VARCHAR(40), UNIQUE(project_id,user_id,submission_key));
CREATE INDEX ix_jobs_state ON jobs(state,lease_until);
CREATE INDEX ix_jobs_project ON jobs(project_id,created_at);
CREATE INDEX ix_datasets_project ON datasets(project_id);
CREATE TABLE job_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, job_id BIGINT NOT NULL REFERENCES jobs(id), stage VARCHAR(20) NOT NULL, message VARCHAR(2000) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE comments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id), experiment_id BIGINT REFERENCES experiments(id), user_id BIGINT NOT NULL REFERENCES users(id), body VARCHAR(2000) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE collaboration_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id), requester_id BIGINT NOT NULL REFERENCES users(id), user_id BIGINT NOT NULL REFERENCES users(id), status VARCHAR(20) NOT NULL DEFAULT 'pending', created_at VARCHAR(40) NOT NULL);
CREATE TABLE audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT REFERENCES users(id), action VARCHAR(200) NOT NULL, record_type VARCHAR(40) NOT NULL, record_id BIGINT NOT NULL, created_at VARCHAR(40) NOT NULL);
